    chapters = {
        {
            chapter = "Kharan's Tale",
            faction = "Alliance",
            summary = "Royal Historian Archesonus, by the High Seat in Ironforge, has a long history of the Dark Iron dwarves to tell. Hear it out. King Magni has questions about his daughter, Moira, and the answers lie in Blackrock Depths.",
            recap = "If you want to understand Princess Moira, the Royal Historian in Ironforge will explain, and it takes a while. The Dark Irons, the War of the Three Hammers, and how the Burning Steppes came to be burning. Then, so I'd really understand, I was sent out to the Ruins of Thaurissan to read the old relics myself. History lessons, in the hottest classroom in the Eastern Kingdoms.\n\nThat was the warm-up. King Magni wanted me to find Kharan Mighthammer, a prisoner deep in Blackrock Depths. Kharan had a tale about Moira. I listened. It was not the tale Magni wanted.\n\nThen I had to go back to Ironforge and tell him. Here's some free advice. If you're ever handed bad news for a king about his daughter, see if anyone else is going that way.",
            quests = {
                { id = 3702, name = "The Smoldering Ruins of Thaurissan", npc = "Royal Historian Archesonus" },
                { id = 3701, name = "The Smoldering Ruins of Thaurissan", displayName = "Burning Steppes", npc = "Royal Historian Archesonus" },
                { id = 4341, name = "Kharan Mighthammer", npc = "King Magni Bronzebeard" },
                { id = 4342, name = "Kharan's Tale", npc = "Kharan Mighthammer" },
                { id = 4361, name = "The Bearer of Bad News", npc = "Kharan Mighthammer" },
            },
        },
        {
            chapter = "The Royal Rescue",
            faction = "Alliance",
            summary = "King Magni has heard enough. His orders from the High Seat are plain: back into Blackrock Depths, through the Dark Iron city to Emperor Dagran Thaurissan, and bring Princess Moira home.",
            recap = "Magni's orders were plain. Back into Blackrock Depths, kill Emperor Dagran Thaurissan, and bring Moira home.\n\nBlackrock Depths is a city, not a cellar, and the emperor sits at the far end of it. We got there. We did the first part. The emperor went down, and I turned around to rescue the princess.\n\nThe princess did not want rescuing. She'd married him, and she was mourning her husband. She also had news. She was carrying his child, and that child would be heir to Ironforge.\n\nThat news went back to her father by way of me. Of every report I've ever made, that's the one where I most wished I'd taken the long road. Magni wanted his daughter back. What he got was a grandchild, and a problem nobody could kill.",
            quests = {
                { id = 4362, name = "The Fate of the Kingdom", npc = "King Magni Bronzebeard" },
                { id = 4363, name = "The Princess's Surprise", npc = "Princess Moira Bronzebeard" },
                { id = 3801, name = "Dark Iron Legacy", npc = "Franclorn Forgewright", optional = true },
                { id = 3802, name = "Dark Iron Legacy", npc = "Franclorn Forgewright", optional = true, afterQuest = 3801, recap = "Franclorn Forgewright, the architect of the Dark Iron city, only appears to the dead, so the first thing I had to do was die. Franclorn's hammer, Ironfel, was in the hands of Fineous Darkvire. I took it back and laid it in the hands of Franclorn's statue, and a little door in the base opened on the key to the city." },
                -- A Taste of Flame needs the Black Dragonflight Molt from Velarok Windblade's Torch of Retribution.
                { id = 3441, name = "Divine Retribution", npc = "Velarok Windblade", optional = true, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3442, name = "The Flawless Flame", npc = "Velarok Windblade", optional = true, afterQuest = 3441, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3443, name = "Forging the Shaft", npc = "Velarok Windblade", optional = true, afterQuest = 3442, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3452, name = "The Flame's Casing", npc = "Velarok Windblade", optional = true, afterQuest = 3443, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3453, name = "The Torch of Retribution", npc = "Velarok Windblade", optional = true, afterQuest = 3452, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3454, name = "The Torch of Retribution", npc = "Velarok Windblade", optional = true, afterQuest = 3453, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3462, name = "Squire Maltrake", npc = "Velarok Windblade", optional = true, afterQuest = 3454, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3463, name = "Set Them Ablaze!", npc = "Squire Maltrake", optional = true, afterQuest = 3462, mapID = 32, x = 0.3900, y = 0.3900 },
                { id = 3481, name = "Trinkets...", npc = "Hoard of the Black Dragonflight", optional = true, afterQuest = 3463, mapID = 32, x = 0.3900, y = 0.3890 },
                { id = 4022, altIds = { 4023 }, name = "A Taste of Flame", npc = "Cyrus Therepentous", optional = true, afterQuest = 3481, recap = "In Searing Gorge, Velarok Windblade told me a story about the black dragonflight and asked for help paying them back. Paying them back took four hearts of flame, four globes of golem oil, eight thorium-plated daggers and a Symbol of Ragnaros, all for the Torch of Retribution. Squire Maltrake then had me carry it into the four sentry towers and set each one ablaze, and the chest that opened afterwards held a black dragonflight molt. Cyrus Therepentous in the Burning Steppes wanted to see it." },
                { id = 4024, name = "A Taste of Flame", npc = "Cyrus Therepentous", optional = true, afterQuest = 4022, recap = "Cyrus Therepentous, out in the Burning Steppes, wanted to taste the fire of Blackrock. Not a request I get often. The fire was Bael'Gar, a giant of pure flame down in the depths. Once Bael'Gar was dead, a scrap of altered dragon molt drew out the essence. Cyrus snatched it from me and told me to take my reward and get out of sight." },
                { id = 4324, name = "Yuka Screwspigot", npc = "Yorba Screwspigot", optional = true, breadcrumbFor = 4136 },
                { id = 4136, name = "Ribbly Screwspigot", npc = "Yuka Screwspigot", optional = true, recap = "Yuka Screwspigot at Flame Crest had a relative to collect: Ribbly, who'd spent the family's money on one scheme after another and was hiding in Blackrock Depths. Booty Bay had put a bounty on Ribbly, and the family was delighted. Ribbly was finally worth something. Yuka wanted Ribbly back alive, if possible. It wasn't." },
                { id = 4123, name = "The Heart of the Mountain", npc = "Maxwort Uberglint", optional = true, recap = "Maxwort Uberglint at Flame Crest had wanted the Heart of the Mountain for years, a gem the size of your fist, and the Dark Irons wouldn't sell. So I let myself into their vault. You open every coffer in the place before the safe's watchman turns up, and then the watchman has to go. Maxwort was delighted. The Dark Irons, less so." },
                { id = 4262, name = "Overmaster Pyron", npc = "Jalinda Sprig", optional = true },
                { id = 4263, name = "Incendius!", npc = "Jalinda Sprig", optional = true, afterQuest = 4262, recap = "Jalinda Sprig at Morgan's Vigil couldn't get a team into the mountain while Lord Incendius kept raising Overmaster Pyron from the ashes. So Incendius had to go. When I reported that Incendius had said the name Ragnaros, Jalinda asked if I was sure, patted my wrist and drifted off into deep thought. I was sure. I'd rather not have been." },
                { id = 4286, name = "The Good Stuff", npc = "Oralius", optional = true, recap = "Oralius at Morgan's Vigil talks like a pirate and was convinced the Dark Irons kept the good stuff in their fanny packs. I brought back twenty. Oralius sniffed through the pile, very happy with the goodies, and let me keep one. I'm still not sure what the good stuff was. I'm not sure I want to know." },
                { id = 4128, name = "Ragnar Thunderbrew", npc = "Enohar Thunderbrew", optional = true, breadcrumbFor = 4126 },
                { id = 4126, name = "Hurley Blackbreath", npc = "Ragnar Thunderbrew", optional = true, recap = "Ragnar Thunderbrew in Kharanos had a grievance: the Dark Irons had stolen the family lager recipe. Ragnar wanted every keg of it in Blackrock Depths smashed and the recipe brought home, and called the thieves villains who didn't deserve such a fine brew. Hurley Blackbreath, who had it, disagreed. Briefly. Part of my pay was lager." },
                { id = 4201, name = "The Love Potion", npc = "Mistress Nagmara", optional = true, recap = "Mistress Nagmara, a succubus working the Grim Guzzler, had one customer immune to her charms: Private Rocknot. So she wanted a love potion, and I did the shopping. Gromsblood, silver veins out of the cliff giants of Azshara, and spring water from Un'Goro. Last I saw, Nagmara was mixing it and Rocknot was still drinking. Poor Rocknot." },
                { id = 4083, name = "The Spectral Chalice", npc = "Spectral Chalice", optional = true, recap = "Somewhere in the depths there's a chalice floating in the air, and it takes offerings: two star rubies, twenty gold bars and ten of truesilver. They made no sound going in. For that, Gloom'rel agreed to teach me to smelt dark iron. Easily the most expensive lesson I've ever taken." },
                { id = 7604, name = "A Binding Contract", npc = "Lokhtos Darkbargainer", optional = true, recap = "Lokhtos Darkbargainer sells the Thorium Brotherhood's secrets out of the Grim Guzzler, and everything comes with a contract. Mine had me swear my sulfuron ingot was genuine and not a facsimile, and that TB Ltd. was not responsible for anything that happened if I went looking for Sulfuras. I signed. I got hammer plans and a cheerful good luck." },
            },
        },
        {
            chapter = "The Warchief's Rescue",
            faction = "Horde",
            summary = "Galamav the Marksman in Kargath shows you a crude drawing of an orc, bars scrawled across the face. The orc is Commander Gor'shak, and the bars suggest a prison. Blackrock Depths has a big one.",
            recap = "I was shown a drawing of an orc. Crude, with bars scribbled over the face. That was the whole clue. So I went looking for a prison, and Blackrock Depths has a big one, and in it was Commander Gor'shak.\n\nThe Dark Irons didn't care for us talking, and halfway through they came at us in waves. I made sure the commander lived to finish the story. Another prisoner nearby had the real news: Princess Moira Bronzebeard, kidnapped by the Dark Irons.\n\nThrall heard me out and sent me back in to kill the emperor and free the princess from his spell.\n\nI did the killing. The princess did not look like anyone under a spell. She looked like a widow, carrying the emperor's child, an heir with a claim on Ironforge. I took that back to Orgrimmar and watched the Warchief do some very careful thinking.",
            quests = {
                { id = 3906, name = "Disharmony of Flame", npc = "Thunderheart", recapAfter = 0, recap = "Thunderheart in Kargath sent me into Blackrock Mountain first, to the quarry, where Overmaster Pyron kept watch over the way into the depths. Pyron fell, and the way in was open." },
                { id = 3981, name = "Commander Gor'shak", npc = "Galamav the Marksman" },
                { id = 3982, name = "What Is Going On?", npc = "Commander Gor'shak" },
                { id = 4001, name = "What Is Going On?", npc = "Commander Gor'shak" },
                { id = 4002, name = "The Eastern Kingdoms", npc = "Thrall" },
                { id = 4003, name = "The Royal Rescue", npc = "Thrall" },
                { id = 4004, name = "The Princess Saved?", npc = "Princess Moira Bronzebeard" },
                { id = 4081, name = "KILL ON SIGHT: Dark Iron Dwarves", npc = "WANTED", optional = true },
                { id = 4082, name = "KILL ON SIGHT: High Ranking Dark Iron Officials", npc = "KILL ON SIGHT", optional = true, afterQuest = 4081, recap = "Kargath has its own way of hiring: a poster that says KILL ON SIGHT. The first one listed the Dark Iron rank and file, guardsmen, wardens and footmen. Once Warlord Goretooth had counted those, a second poster went up for the medics, soldiers and officers. I appreciate an employer who puts it in writing." },
                { id = 4122, name = "Grark Lorkrub", npc = "Lexlort", optional = true },
                { id = 4121, name = "Precarious Predicament", npc = "Grark Lorkrub", optional = true, afterQuest = 4122 },
                { id = 4132, name = "Operation: Death to Angerforge", npc = "Warlord Goretooth", optional = true, afterQuest = 4121, recap = "Lexlort in Kargath wanted a traitor, Grark Lorkrub, who'd been feeding our plans to the Blackrock orcs. I shackled Grark in a Blackrock fortress and walked him out through the mountain, hearing all the way that I'd never make it. I made it. Then Warlord Goretooth sent me after General Angerforge, who'd planned the slaughter of the 109th. Also done." },
                { id = 4133, name = "Vivian Lagrave", npc = "Apothecary Zinge", optional = true, breadcrumbFor = 4134 },
                { id = 4134, name = "Lost Thunderbrew Recipe", npc = "Shadowmage Vivian Lagrave", optional = true, recap = "Shadowmage Vivian Lagrave in Kargath wanted a lager recipe the Dark Irons had stolen from some dwarven brewers. The ale is said to make the drinker stronger and braver, and the Forsaken would like to know how. I fetched it, and off it went to the Apothecarium for study. It's the first time I've felt sorry for a beer." },
                { id = 7201, name = "The Last Element", npc = "Shadowmage Vivian Lagrave", optional = true, recap = "The Dark Irons' golems run on something special, and Vivian Lagrave wanted ten essences of it for some Forsaken abominations. Turn the city upside down if you must, I was told. I started with the golems and the dwarves who build them, and never needed to turn anything else over." },
                { id = 3907, name = "Disharmony of Fire", npc = "Thunderheart", optional = true, afterQuest = 3906, recap = "Thunderheart in Kargath felt something foul seeping out of Blackrock Mountain, and wanted Lord Incendius dead on the theory that the servant leads you to the master. Incendius died, and I brought back the Tablet of Kurniya. Thunderheart took it, said the name Ragnaros, and told Kargath to decide whether to stand or run. I've had warmer welcomes." },
                { id = 4061, name = "The Rise of the Machines", npc = "Hierophant Theodora Mulvadania", optional = true, mapID = 15, x = 0.0300, y = 0.4740 },
                { id = 4062, name = "The Rise of the Machines", npc = "Hierophant Theodora Mulvadania", optional = true, afterQuest = 4061, mapID = 15, x = 0.0300, y = 0.4740, recap = "Hierophant Theodora Mulvadania in Kargath wanted ten fractured elemental shards from the golems and elementals of the Burning Steppes. I brought them, and Theodora sent a sample with me to Lotwil Veriatus, camped to the east of Kargath." },
                { id = 4063, name = "The Rise of the Machines", npc = "Lotwil Veriatus", optional = true, afterQuest = 4062, recap = "Lotwil Veriatus was sure Golem Lord Argelmach had died ten years ago, so new machines bearing Argelmach's marks had Lotwil rattled. I brought back Argelmach's head and ten elemental cores from the golems around him. The head was metal, a Dark Iron construct. Lotwil now expects another one, and frankly so do I." },
                { id = 97197, name = "Fragment of the Firelands", npc = "Alaana Stormwalker", optional = true, gameVersions = { forever = true }, recap = "Alaana Stormwalker near Thunder Bluff had word that the wall between our world and the Firelands had cracked somewhere under Blackrock Mountain, and that giants of molten rock were walking through. Alaana called that thrilling and terrifying and wanted a piece of one to study. I brought back a fragment. I'd have gone with terrifying." },
                { id = 3801, name = "Dark Iron Legacy", npc = "Franclorn Forgewright", optional = true },
                { id = 3802, name = "Dark Iron Legacy", npc = "Franclorn Forgewright", optional = true, afterQuest = 3801, recap = "Franclorn Forgewright, the architect of the Dark Iron city, only appears to the dead, so the first thing I had to do was die. Franclorn's hammer, Ironfel, was in the hands of Fineous Darkvire. I took it back and laid it in the hands of Franclorn's statue, and a little door in the base opened on the key to the city." },
                -- A Taste of Flame needs the Black Dragonflight Molt from Velarok Windblade's Torch of Retribution.
