                { id = 4136, name = "Ribbly Screwspigot", npc = "Yuka Screwspigot", optional = true, recap = "Yuka Screwspigot at Flame Crest had a relative to collect: Ribbly, who'd spent the family's money on one scheme after another and was hiding in Blackrock Depths. Booty Bay had put a bounty on Ribbly, and the family was delighted. Ribbly was finally worth something. Yuka wanted Ribbly back alive, if possible. It wasn't." },
                { id = 4123, name = "The Heart of the Mountain", npc = "Maxwort Uberglint", optional = true, recap = "Maxwort Uberglint at Flame Crest had wanted the Heart of the Mountain for years, a gem the size of your fist, and the Dark Irons wouldn't sell. So I let myself into their vault. You open every coffer in the place before the safe's watchman turns up, and then the watchman has to go. Maxwort was delighted. The Dark Irons, less so." },
                { id = 4201, name = "The Love Potion", npc = "Mistress Nagmara", optional = true, recap = "Mistress Nagmara, a succubus working the Grim Guzzler, had one customer immune to her charms: Private Rocknot. So she wanted a love potion, and I did the shopping. Gromsblood, silver veins out of the cliff giants of Azshara, and spring water from Un'Goro. Last I saw, Nagmara was mixing it and Rocknot was still drinking. Poor Rocknot." },
                { id = 4083, name = "The Spectral Chalice", npc = "Spectral Chalice", optional = true, recap = "Somewhere in the depths there's a chalice floating in the air, and it takes offerings: two star rubies, twenty gold bars and ten of truesilver. They made no sound going in. For that, Gloom'rel agreed to teach me to smelt dark iron. Easily the most expensive lesson I've ever taken." },
                { id = 7604, name = "A Binding Contract", npc = "Lokhtos Darkbargainer", optional = true, recap = "Lokhtos Darkbargainer sells the Thorium Brotherhood's secrets out of the Grim Guzzler, and everything comes with a contract. Mine had me swear my sulfuron ingot was genuine and not a facsimile, and that TB Ltd. was not responsible for anything that happened if I went looking for Sulfuras. I signed. I got hammer plans and a cheerful good luck." },
            },
        },
    },
}
